CREATE DATABASE IF NOT EXISTS kasirumkm CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kasirumkm;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('OWNER', 'KASIR') NOT NULL DEFAULT 'KASIR', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, category_id BIGINT NULL, price DECIMAL(15,2) NOT NULL, stock INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT chk_product_price CHECK (price > 0), CONSTRAINT chk_product_stock CHECK (stock >= 0), CONSTRAINT fk_product_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS suppliers (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, phone VARCHAR(40), product VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, phone VARCHAR(40), address VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions (id BIGINT PRIMARY KEY AUTO_INCREMENT, number VARCHAR(50) NOT NULL UNIQUE, user_id BIGINT NOT NULL, customer_id BIGINT NULL, total DECIMAL(15,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_transaction_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_transaction_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS transaction_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, transaction_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, price DECIMAL(15,2) NOT NULL, subtotal DECIMAL(15,2) NOT NULL, CONSTRAINT chk_item_quantity CHECK (quantity > 0), CONSTRAINT fk_item_transaction FOREIGN KEY (transaction_id) REFERENCES transactions(id) ON DELETE CASCADE, CONSTRAINT fk_item_product FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS stock_movements (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, user_id BIGINT NOT NULL, quantity INT NOT NULL, type ENUM('IN', 'OUT') NOT NULL, note VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_stock_product FOREIGN KEY (product_id) REFERENCES products(id), CONSTRAINT fk_stock_user FOREIGN KEY (user_id) REFERENCES users(id));
INSERT IGNORE INTO categories (name) VALUES ('Minuman'), ('Makanan'), ('Snack');